### 6.1 JSON Serialization

**Standard JSON Format**:

```python
import json
from datetime import datetime
from decimal import Decimal

class FusionJSONEncoder(json.JSONEncoder):
    """Custom JSON encoder for Fusion Redis data."""

    def default(self, obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        elif isinstance(obj, Decimal):
            return str(obj)
        elif hasattr(obj, '__dict__'):
            return obj.__dict__
        return super().default(obj)

def serialize_for_redis(data: dict) -> str:
    """Serialize data for Redis storage."""
    return json.dumps(data, cls=FusionJSONEncoder, sort_keys=True)

def deserialize_from_redis(data: str) -> dict:
    """Deserialize data from Redis."""
    return json.loads(data)

# Usage examples
user_data = {
    "id": "user456",
    "email": "user@example.com",
    "created_at": datetime.utcnow(),
    "balance": Decimal("123.45")
}

serialized = serialize_for_redis(user_data)
redis_client.set("fusion:auth:tenant123:user:user456", serialized)
```

