### 9.2 Data Cleanup

**Automated Cleanup Patterns**:

```python
def cleanup_expired_data(tenant_id: str, dry_run: bool = True):
    """Clean up expired data that doesn't have TTL set."""
    cleanup_stats = {
        "expired_sessions": 0,
        "old_activities": 0,
        "stale_cache": 0
    }

    # Clean up old sessions (older than 7 days)
    session_pattern = f"fusion:auth:{tenant_id}:session:*"
    sessions = redis_client.keys(session_pattern)

    cutoff_time = datetime.utcnow() - timedelta(days=7)
    cutoff_timestamp = int(cutoff_time.timestamp())

    for session_key in sessions:
        session_data = redis_client.hgetall(session_key)
        if session_data:
            created_at = session_data.get(b"created_at", b"").decode()
            if created_at:
                try:
                    session_time = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
                    if session_time.timestamp() < cutoff_timestamp:
                        if not dry_run:
                            redis_client.delete(session_key)
                        cleanup_stats["expired_sessions"] += 1
                except ValueError:
                    continue

    # Clean up old activity logs (keep only last 1000 per user)
    activity_pattern = f"fusion:auth:{tenant_id}:user:*:activity"
    activity_keys = redis_client.keys(activity_pattern)

    for activity_key in activity_keys:
        activity_count = redis_client.llen(activity_key)
        if activity_count > 1000:
            if not dry_run:
                redis_client.ltrim(activity_key, 0, 999)
            cleanup_stats["old_activities"] += (activity_count - 1000)

    return cleanup_stats
```
